#define N 24
static const char* map[N]={"########################","#......................#","#.###...###...###...####","#.###...###...###...####","#......................#","#......................#","#......................#","#.###...###...###...####","#.###...###...###...####","#......................#","#......................#","#......................#","#.###...###...###...####","#.###...###...###...####","#......................#","#......................#","#......................#","#.###...###...###...####","#......................#","#....R.........R.......#","#......................#","#..HHHHHHHH............#","#..HHHHHHHH............#","########################"};
typedef struct {float x,y,a; int ride,pending,anim,action,jump; bool armed,firelock; float nx[6],ny[6]; bool alive[6]; unsigned phase; bool chord; float vx[8],vy[8]; float depth[128]; bool keys[6],car,quit; unsigned cash,mission; FuriMessageQueue* q; FuriMutex* lock;} Game;
static bool wall(float x,float y){int a=(int)x,b=(int)y;return x<0||y<0||a>=N||b>=N||(map[b][a]=='#'||map[b][a]=='H');}
static void vehicle(Canvas* c,int x,int y,int w,int h,bool bike){if(w<3||h<3)return;canvas_set_color(c,ColorWhite);canvas_draw_box(c,x,y,w,h);canvas_set_color(c,ColorBlack);if(bike){canvas_draw_disc(c,x+w/4,y+h-2,2);canvas_draw_disc(c,x+3*w/4,y+h-2,2);canvas_draw_line(c,x+w/4,y+h-2,x+w/2,y);canvas_draw_line(c,x+w/2,y,x+3*w/4,y+h-2);canvas_draw_line(c,x+w/2,y,x+w-1,y);}else{canvas_draw_rbox(c,x,y+h/3,w,h-h/3,2);canvas_draw_frame(c,x+w/5,y,w*3/5,h/2);canvas_set_color(c,ColorWhite);canvas_draw_line(c,x+2,y+h/2,x+w/3,y+h/2);canvas_draw_line(c,x+2*w/3,y+h/2,x+w-3,y+h/2);canvas_set_color(c,ColorBlack);}}
static void hero(Canvas* c,unsigned phase,int action,int anim,bool armed){int frame=(phase/3)%4,step=frame==1?3:frame==3?-3:0;int x=64+(action==1||action==2?(8-anim)*2:0),y=30;canvas_set_color(c,ColorWhite);canvas_draw_box(c,x-10,y-2,21,24);canvas_set_color(c,ColorBlack);canvas_draw_rbox(c,x-4,y,8,7,2);canvas_set_color(c,ColorWhite);canvas_draw_line(c,x-3,y+5,x+3,y+5);canvas_set_color(c,ColorBlack);canvas_draw_frame(c,x-6,y+8,13,10);canvas_draw_line(c,x-5,y+8,x-3,y+11);canvas_draw_line(c,x+5,y+8,x+3,y+11);canvas_draw_line(c,x-3,y+16,x+3,y+16);canvas_draw_line(c,x-7,y+8,x-9,y+14+step);canvas_draw_line(c,x+7,y+8,x+9,y+14-step);canvas_draw_box(c,x-5,y+17,4,5);canvas_draw_box(c,x+2,y+17,4,5);canvas_draw_line(c,x-4,y+21,x-5-step,y+23);canvas_draw_line(c,x+3,y+21,x+5+step,y+23);if(armed||action==3){int h=action==3?anim/2:0;canvas_draw_line(c,x+7,y+10,x+12,y+7+h);canvas_draw_box(c,x+11,y+5+h,5,2);}if(action==4)canvas_draw_line(c,x+15,y+5,x+19,y+2);}
static void palm(Canvas* c,int x,int y,int h){if(h<5)return;int t=y-h;canvas_draw_line(c,x,y,x-2,t);canvas_draw_line(c,x+1,y,x-1,t);for(int i=-2;i<=2;i++){int ex=x+i*h/4;canvas_draw_line(c,x-2,t,ex,t-2);canvas_draw_line(c,ex,t-2,ex+i,t+3);}}
typedef struct {float x,y,z;} Point3;
static bool project(Point3 p,float cx,float cy,float dx,float dy,int* x,int* y){float a=p.x-cx,b=p.y-cy,d=a*dx+b*dy;if(d<.18f)return false;*x=64+(int)((-a*dy+b*dx)*55/d);*y=27+(int)((.95f-p.z)*55/d);return *x>=-120&&*x<=248&&*y>=-100&&*y<=164;}
static void edge3(Canvas* c,Point3 a,Point3 b,float cx,float cy,float dx,float dy){int x,y,u,v;if(project(a,cx,cy,dx,dy,&x,&y)&&project(b,cx,cy,dx,dy,&u,&v)&&x>=0&&x<128&&u>=0&&u<128&&y>=9&&y<54&&v>=9&&v<54)canvas_draw_line(c,x,y,u,v);}
static void block3(Canvas* c,float x,float y,float h,float cx,float cy,float dx,float dy){Point3 p[8]={{x,y,0},{x+1,y,0},{x+1,y+1,0},{x,y+1,0},{x,y,h},{x+1,y,h},{x+1,y+1,h},{x,y+1,h}};for(int j=0;j<4;j++){edge3(c,p[j],p[(j+1)%4],cx,cy,dx,dy);edge3(c,p[j+4],p[(j+1)%4+4],cx,cy,dx,dy);edge3(c,p[j],p[j+4],cx,cy,dx,dy);}}
static void draw(Canvas* c,void* ctx){Game* g=ctx;furi_mutex_acquire(g->lock,FuriWaitForever);canvas_clear(c);for(int i=0;i<3;i++){int x=(i*40+12+(int)(g->a*8))%100;if(x<0)x+=100;canvas_draw_line(c,x,25,x+12,12+i*3);canvas_draw_line(c,x+12,12+i*3,x+25,25);}float dx=cosf(g->a),dy=sinf(g->a);float cx=g->x,cy=g->y;for(float d=.1f;d<.9f;d+=.1f){if(wall(g->x-d*dx,g->y-d*dy))break;cx=g->x-d*dx;cy=g->y-d*dy;}
for(int x=0;x<128;x+=2){float off=(x-64)/55.f,rx=dx-dy*off,ry=dy+dx*off,d=.05f;while(d<15&&!wall(cx+rx*d,cy+ry*d))d+=.07f;g->depth[x]=g->depth[x+1]=d;}
for(int yy=0;yy<N;yy++)for(int xx=0;xx<N;xx++){if(map[yy][xx]!='#'&&map[yy][xx]!='H')continue;if(fabsf(xx-cx)>9||fabsf(yy-cy)>9)continue;float h=map[yy][xx]=='H'?2.7f:1.1f+((xx+yy)%3)*.55f;block3(c,xx,yy,h,cx,cy,dx,dy);}
for(int k=0;k<N;k++){if(k%5==1||k%5==4){edge3(c,(Point3){1,k,0},(Point3){22,k,0},cx,cy,dx,dy);}}
for(int i=0;i<5;i++){int y=30+i*i;canvas_draw_line(c,63-i/2,y,64+i/2,y);}for(int i=0;i<10;i++){float ax=1.5f+i*2-cx,ay=4.5f-cy,z=ax*dx+ay*dy;if(z<.6f)continue;int sx=64+(int)((-ax*dy+ay*dx)*98/z);if(sx<8||sx>119||z>g->depth[sx])continue;int h=(int)(27/z);if(h>28)h=28;int y=28+(int)(17/z);if(y>53)y=53;palm(c,sx,y,h);}
for(int i=0;i<8;i++){if(i==g->ride)continue;float ax=g->vx[i]-cx,ay=g->vy[i]-cy,z=ax*dx+ay*dy,side=-ax*dy+ay*dx;if(z<.2f)continue;int sx=64+(int)(side*98/z);if(sx<4||sx>123||z>g->depth[sx])continue;int w=(int)((i%3==2?9:18)/z),h=(int)(12/z);if(w>28)w=28;if(h>18)h=18;int bottom=28+(int)(17/z);if(bottom>53)bottom=53;if(sx-w/2<0||sx+w/2>127)continue;vehicle(c,sx-w/2,bottom-h,w,h,i%3==2);}
for(int i=0;i<6;i++){if(!g->alive[i])continue;float ax=g->nx[i]-cx,ay=g->ny[i]-cy,z=ax*dx+ay*dy;if(z<.3f)continue;int sx=64+(int)((-ax*dy+ay*dx)*98/z);if(sx<5||sx>122||z>g->depth[sx])continue;int h=(int)(18/z);if(h>22)h=22;if(h<4)continue;int y=28+(int)(12/z);if(y>53)y=53;canvas_draw_disc(c,sx,y-h,h/6);canvas_draw_line(c,sx,y-h+2,sx,y-h/3);canvas_draw_line(c,sx-2,y-h/2,sx+2,y-h/2);canvas_draw_line(c,sx,y-h/3,sx-2,y);canvas_draw_line(c,sx,y-h/3,sx+2,y);}
for(int i=0;i<2;i++){float ax=(i?15.5f:5.5f)-cx,ay=19.5f-cy,z=ax*dx+ay*dy;if(z<.4f)continue;int sx=64+(int)((-ax*dy+ay*dx)*98/z);if(sx<8||sx>119||z>g->depth[sx])continue;int y=28+(int)(12/z);if(y>53)y=53;canvas_draw_line(c,sx-7,y,sx+7,y-6);canvas_draw_line(c,sx+7,y-6,sx+7,y);canvas_draw_line(c,sx-7,y,sx+7,y);}
if(g->ride>=0){vehicle(c,53,36-g->jump,22,17,g->ride%3==2);if(g->ride%3==2)canvas_draw_disc(c,64,34-g->jump,3);}else hero(c,g->phase,g->action,g->anim,g->armed);
canvas_set_color(c,ColorWhite);canvas_draw_box(c,0,0,128,9);canvas_draw_box(c,0,54,128,10);canvas_set_color(c,ColorBlack);canvas_set_font(c,FontSecondary);char s[40];snprintf(s,sizeof(s),"$%u  %s",g->cash,g->ride<0?"JASON":g->ride%3==2?"BIKE":"CAR");canvas_draw_str(c,1,8,s);canvas_draw_str(c,84,8,"VC 0.5");canvas_draw_str(c,1,63,g->armed?"HP100 GUN":"HP100");snprintf(s,sizeof(s),"M%u: %d,%d",g->mission+1, g->mission%2?1:20,g->mission%2?1:14);canvas_draw_str(c,48,63,s);canvas_draw_frame(c,105,10,22,22);for(int y=0;y<N;y+=2)for(int x=0;x<N;x+=2)if(map[y][x]=='#'||map[y][x]=='H')canvas_draw_dot(c,108+x/2,13+y/2);canvas_draw_disc(c,108+(int)g->x/2,13+(int)g->y/2,1);furi_mutex_release(g->lock);}
static void input(InputEvent* e,void* ctx){Game* g=ctx;furi_message_queue_put(g->q,e,0);}
int32_t gta_main(void* p){UNUSED(p);Game* g=calloc(1,sizeof(Game));if(!g)return -1;g->x=1.5f;g->y=1.5f;g->ride=-1;g->pending=-1;for(int i=0;i<6;i++){g->nx[i]=2.5f+i*3;g->ny[i]=9.5f;g->alive[i]=true;}float vx[8]={3.5,7.5,12.5,2.5,9.5,13.5,5.5,11.5},vy[8]={1.5,4.5,5.5,8.5,9.5,14.5,14.5,1.5};for(int i=0;i<8;i++){g->vx[i]=vx[i];g->vy[i]=vy[i];}g->q=furi_message_queue_alloc(16,sizeof(InputEvent));g->lock=furi_mutex_alloc(FuriMutexTypeNormal);ViewPort* v=view_port_alloc();view_port_draw_callback_set(v,draw,g);view_port_input_callback_set(v,input,g);Gui* gui=furi_record_open(RECORD_GUI);gui_add_view_port(gui,v,GuiLayerFullscreen);while(!g->quit){InputEvent e;bool got=furi_message_queue_get(g->q,&e,30)==FuriStatusOk;furi_mutex_acquire(g->lock,FuriWaitForever);if(got){if(e.key==InputKeyBack&&e.type==InputTypeShort)g->quit=true;if(e.key<6){if(e.type==InputTypePress)g->keys[e.key]=true;if(e.type==InputTypeRelease)g->keys[e.key]=false;}}bool combo=g->keys[InputKeyDown]&&g->keys[InputKeyOk];if(combo&&!g->chord&&!g->anim){if(g->ride>=0){g->ride=-1;float ex=g->x-sinf(g->a)*.65f,ey=g->y+cosf(g->a)*.65f;if(!wall(ex,ey)){g->x=ex;g->y=ey;}}else{float best=1.44f;int near=-1;for(int i=0;i<8;i++){float ax=g->x-g->vx[i],ay=g->y-g->vy[i],d=ax*ax+ay*ay;if(d<best){best=d;near=i;}}if(near>=0){g->pending=near;g->action=near%3==2?2:1;g->anim=8;}}}g->chord=combo;bool gun=g->keys[InputKeyLeft]&&g->keys[InputKeyOk];bool shot=g->keys[InputKeyRight]&&g->keys[InputKeyOk];if((gun||shot)&&!g->firelock&&g->ride<0&&!g->anim){if(gun){g->armed=!g->armed;g->action=3;g->anim=8;}else if(g->armed){g->action=4;g->anim=4;for(int i=0;i<6;i++){float ax=g->nx[i]-g->x,ay=g->ny[i]-g->y,d=ax*cosf(g->a)+ay*sinf(g->a),side=-ax*sinf(g->a)+ay*cosf(g->a);if(g->alive[i]&&d>0&&d<5&&fabsf(side)<.4f){bool clear=true;for(float t=.1f;t<d;t+=.1f)if(wall(g->x+cosf(g->a)*t,g->y+sinf(g->a)*t))clear=false;if(clear){g->alive[i]=false;break;}}}}}g->firelock=gun||shot;if(g->anim&&!--g->anim){if(g->pending>=0){g->ride=g->pending;g->pending=-1;g->x=g->vx[g->ride];g->y=g->vy[g->ride];}g->action=0;}if(g->keys[InputKeyLeft]&&!gun)g->a-=.09f;if(g->keys[InputKeyRight]&&!shot)g->a+=.09f;float speed=(g->ride>=0?(g->ride%3==2?.20f:.15f):g->keys[InputKeyOk]?.11f:.07f)*(g->keys[InputKeyUp]-(g->keys[InputKeyDown]&&!combo));if(g->anim)speed=0;if(g->jump>0)g->jump--;if(g->ride>=0&&speed>0&&map[(int)g->y][(int)g->x]=='R'&&!g->jump)g->jump=10;for(int i=0;i<6;i++){float nx=g->nx[i]+.025f*cosf(g->phase*.03f+i);if(!wall(nx,g->ny[i]))g->nx[i]=nx;}float x=g->x+cosf(g->a)*speed,y=g->y+sinf(g->a)*speed;if(!wall(x,g->y))g->x=x;if(!wall(g->x,y))g->y=y;if(speed!=0)g->phase++;else g->phase=0;if(g->ride>=0){g->vx[g->ride]=g->x;g->vy[g->ride]=g->y;}float target=g->mission%2?1.5f:20.5f;if(fabsf(g->x-target)<.6f&&fabsf(g->y-target)<.6f){g->cash+=250;g->mission++;}furi_mutex_release(g->lock);view_port_update(v);}gui_remove_view_port(gui,v);view_port_free(v);furi_record_close(RECORD_GUI);furi_message_queue_free(g->q);furi_mutex_free(g->lock);free(g);return 0;}